#!/usr/bin/env bash
#
# Check that the hand edits inside Token Workbench.dc.html survived.
#
# That file is GENERATED by Claude Design. A re-export from a design session can
# silently drop these edits — no conflict, no error. Search would just quietly
# start dead-ending again and the motion tokens would render nothing again.
#
# Run this after any Claude Design session, before merging its branch.
#
set -uo pipefail
cd "$(dirname "$0")"
F='Token Workbench.dc.html'
[ -f "$F" ] || { echo "✗ $F not found"; exit 1; }

fail=0
check() { # name expected description
  local n; n=$(grep -o -F -- "$1" "$F" | wc -l | tr -d ' ')
  if [ "$n" -ge "$2" ]; then
    printf '  ✓ %-50s %2s  %s\n' "$1" "$n" "$3"
  else
    printf '  ✗ %-50s %2s  MISSING (expected >=%s) — %s\n' "$1" "$n" "$2" "$3"
    fail=1
  fi
}

echo "Workbench integrity — hand edits inside a generated file"
echo
# Patterns are anchored to surrounding syntax on purpose. A bare identifier is a
# substring of its own mangled form ("qHitsInGroup" matches "qHitsInGroupX"), so
# an unanchored check would pass a rename and report a false all-clear.
check 'const qHitsInGroup ='                        1 'search fix: the guard is computed (PR #5)'
check '!qHitsInGroup ||'                            1 'search fix: the guard is applied (PR #5)'
check '@keyframes jf-motion-travel {'               1 'motion: the keyframes exist (PR #6)'
check 'animation:jf-motion-travel var(--t-motion-'  3 'motion: all three tracks are token-driven (PR #6)'
check "u:'Motion & density board'"                  8 'used_in metadata tells the truth (PR #6)'
check "['Assets',5]"                                1 'specimen count includes the new board (PR #6)'
echo

if [ "$fail" = 0 ]; then
  echo "✓ all present — safe to merge"
else
  cat <<'MSG'
✗ one or more edits were lost, almost certainly by a Claude Design re-export.

  See exactly what changed:
      git diff pre-design-sync -- 'Token Workbench.dc.html'

  Recover just this file, keeping everything else from the session:
      git checkout pre-design-sync -- 'Token Workbench.dc.html'

  ...then re-apply the design changes you actually wanted on top.
MSG
fi
exit "$fail"
